fn frame(t: i32) {
    let w: i32 = host::display::width();
    let h: i32 = host::display::height();
    let ground: i32 = h - 10;
    let down: i32 = host::display::pointer_down();
    let was: i32 = host::display::state_get(1);
    host::display::state_set(1, down);
    let mut flying: i32 = host::display::state_get(2);
    if flying == 0 && down == 1 && was == 0 {
        flying = 1;
        host::display::state_set(3, 14 * 16);
        host::display::state_set(4, (ground - 14) * 16);
        host::display::state_set(5, 58);
        host::display::state_set(6, 0 - 110);
    }
    host::display::clear(0x000000);
    host::display::fill_rect(0, ground, w, h - ground, 0x304020);
    host::display::fill_rect(6, ground - 14, 18, 14, 0x707070);
    host::display::draw_line(15, ground - 14, 30, ground - 30, 0x707070);
    if flying == 1 {
        let mut x: i32 = host::display::state_get(3) + host::display::state_get(5);
        let mut vy: i32 = host::display::state_get(6) + 4;
        let mut y: i32 = host::display::state_get(4) + vy;
        if y > (ground - 6) * 16 || x > w * 16 {
            flying = 0;
        }
        host::display::state_set(3, x);
        host::display::state_set(4, y);
        host::display::state_set(6, vy);
        host::display::fill_rect(x / 16, y / 16, 6, 6, 0xffe080);
        host::display::draw_string(8, 8, "FLYING", 0x808080, 1);
    } else {
        host::display::draw_string(8, 8, "TAP TO FIRE", 0xffffff, 1);
    }
    host::display::state_set(2, flying);
    host::display::present();
}
